const API_PATH = '/web-apps/apps/api/documents/api.js'

const ALLOWED_PROTOCOLS = ['https:', 'http:']

/**
 * Builds the URL of the OnlyOffice editor API from the document server URL.
 *
 * A received drive's `/open` response is proxied to its owner and may be
 * attacker-controlled. Pin its script path to the origin to prevent query,
 * fragment and download-path smuggling. Only responses generated by the local
 * stack may retain a configured reverse-proxy prefix.
 *
 * @param {unknown} serverUrl - `onlyoffice.url` from the `/open` response
 * @param {object} [options]
 * @param {boolean} [options.isServerUrlTrusted=false] Whether the response was generated locally
 * @returns {string|null} the API URL, or null for an invalid HTTP(S) URL
 */
export function makeOfficeApiUrl(
  serverUrl,
  { isServerUrlTrusted = false } = {}
) {
  if (typeof serverUrl !== 'string' || serverUrl === '') return null

  let parsed
  try {
    parsed = new URL(serverUrl)
  } catch {
    return null
  }

  if (!ALLOWED_PROTOCOLS.includes(parsed.protocol)) return null

  const apiUrl = new URL(API_PATH, parsed.origin)
  if (isServerUrlTrusted) {
    apiUrl.pathname = `${parsed.pathname.replace(/\/+$/, '')}${API_PATH}`
  }

  return apiUrl.toString()
}
